+}
+
+/** Same output as parseLegacyCsv, but handles quoted cells. */
+export function parseImportCsv(text: string): LegacyRow[] {
+  const [headerCells, ...records] = parseCsvRecords(text);
+  if (!headerCells) return [];
+  const header = headerCells.map((h) => h.trim().toLowerCase());
+
+  return records.map((cells) => {
+    const get = (name: string): string => (cells[header.indexOf(name)] ?? '').trim();
